function logoSrc(u) {
  if (u.logoUrl) return u.logoUrl;              // custom logo from DB (preferred)
  if (!u.website) return '';
  return LOGO_OVERRIDES[u.website] || `https://www.google.com/s2/favicons?domain=${u.website}&sz=128`;
}

function handleLogoError(img, domain, fallback) {
  img.parentElement.innerHTML = fallback;
}
function checkLogoSize(img, fallback) {
  // If favicon came back tiny (≤20px) replace with emoji — looks far better than a blurry 16px icon
  if (img.naturalWidth <= 20) img.parentElement.innerHTML = fallback;
}

